-- 插入（显式列名最稳妥：加列后旧语句不会错位）
INSERT INTO employee (emp_id, name, ‹1›, salary)
VALUES (1, 'Alice', 10, 6000.00),
       (2, 'Bob',   20, 8000.00);

-- 从查询结果插入
INSERT INTO ‹2› (emp_id, name)
SELECT emp_id, name FROM employee WHERE ‹3› = 0;

-- 更新（务必带 WHERE）
UPDATE employee SET salary = 6500.00 WHERE emp_id = 1;

-- 删除（务必带 WHERE）
DELETE FROM employee WHERE emp_id = 2;
